#!/usr/bin/env node
// Writes fixtures/issuance-cases.json: the hand-authored conformance cases.
// Expectations here are written from the specification (the check order in lib.rs and
// docs/ISSUANCE-SPEC.md), not generated by either implementation. Both runners must
// meet every expectation, and their full transcripts must also be byte-identical.
//
// Usage: node fixtures/build-cases.mjs [--check]   (--check fails if the file is stale)

import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const OUT = join(dirname(fileURLToPath(import.meta.url)), 'issuance-cases.json');
const U64_MAX = ((1n << 64n) - 1n).toString();
const U128_MAX = ((1n << 128n) - 1n).toString();
const MAX_RETIRE_WH = (((1n << 63n) - 1n) / 10n).toString(); // 922337203685477580
const RELAY = ['proposer', 'verifier'];
const GOV = ['governance'];

// ----- step helpers: every value that is an integer in Rust is a decimal string -------
const s = (v) => String(v);
const reg = (site, { responsible = 'alice', cls = 1, next_seq = 0, auth = GOV, expect = 'ok' } = {}) =>
  ({ op: 'register_site', args: { site, responsible, class: cls, next_seq: s(next_seq) }, auth, expect });
const acc = (site, seq, cumulative_mwh, { level = 2, batch, auth = RELAY, expect = 'ok', accrued_wh } = {}) => {
  const st = { op: 'accrue', args: { site, seq: s(seq), cumulative_mwh: s(cumulative_mwh), batch: batch ?? `${site}#${seq}`, level }, auth, expect };
  if (accrued_wh !== undefined) st.expect_value = { accrued_wh: s(accrued_wh) };
  return st;
};
const ret = (site, start_wh, end_wh, statement, { auth = ['alice'], expect = 'ok' } = {}) =>
  ({ op: 'retire', args: { site, start_wh: s(start_wh), end_wh: s(end_wh), statement }, auth, expect });
const frz = (site, frozen, { auth = GOV, expect = 'ok' } = {}) => ({ op: 'set_frozen', args: { site, frozen }, auth, expect });
const pause = (paused, { auth = GOV, expect = 'ok' } = {}) => ({ op: 'set_paused', args: { paused }, auth, expect });
const relay = (proposer, verifier, { auth = GOV, expect = 'ok' } = {}) => ({ op: 'set_relay', args: { proposer, verifier }, auth, expect });
const err = (code) => ({ err: code });

// A live site with some verified energy, used by many cases.
const liveSite = (wh = 10_000) => [reg('roof'), acc('roof', 0, wh * 1000, { accrued_wh: wh })];
const simSite = (wh = 10_000) => [reg('sim', { cls: 0 }), acc('sim', 0, wh * 1000, { level: 0, accrued_wh: wh })];

const cases = [];
const add = (id, title, covers, steps, final) => cases.push({ id, title, covers, steps, ...(final ? { final } : {}) });

// ----- happy path and flooring ---------------------------------------------------------
add('I01', 'SOW example: 412,000 Wh accrued and retired once (0.412 QWATT minted and burned in one call)', ['accrual', 'retirement', 'zero-supply'], [
  reg('roof'), acc('roof', 0, 412_000_000, { accrued_wh: 412_000 }),
  ret('roof', 0, 412_000, 'January allocation to six apartments (fictional)'),
], { roof: { accrued_wh: '412000', retired_wh: '412000', next_seq: '1' } });
add('I02', 'Flooring: 999 mWh verifies 0 Wh; nothing can be retired', ['flooring', 'min-ab'], [
  reg('roof'), acc('roof', 0, 999, { accrued_wh: 0 }), ret('roof', 0, 1, 's', { expect: err('OverRetire') }),
], { roof: { accrued_wh: '0', retired_wh: '0' } });
add('I03', 'Flooring: 1,000 mWh verifies exactly 1 Wh', ['flooring'], [
  reg('roof'), acc('roof', 0, 1000, { accrued_wh: 1 }), ret('roof', 0, 1, 's'),
], { roof: { accrued_wh: '1', retired_wh: '1' } });
add('I04', 'Flooring: 1,001 mWh verifies 1 Wh; the remainder is carried, never rounded up', ['flooring'], [
  reg('roof'), acc('roof', 0, 1001, { accrued_wh: 1 }), acc('roof', 1, 1999, { accrued_wh: 1 }), acc('roof', 2, 2000, { accrued_wh: 2 }),
], { roof: { cumulative_mwh: '2000', accrued_wh: '2' } });
add('I05', 'min(A,B) rule: a claim equal to the verified amount passes, one Wh more is refused', ['min-ab', 'over-retire'], [
  ...liveSite(500), ret('roof', 0, 501, 'too much', { expect: err('OverRetire') }), ret('roof', 0, 500, 'exact'),
], { roof: { retired_wh: '500' } });
add('I06', 'Rejected batch carries no energy: equal cumulative is accepted and accrues nothing', ['accrual', 'monotonic'], [
  ...liveSite(10), acc('roof', 1, 10_000, { accrued_wh: 10 }),
], { roof: { next_seq: '2', accrued_wh: '10' } });
add('I07', 'Contiguous retirements consume [0,a), [a,b), [b,c)', ['ranges'], [
  ...liveSite(300), ret('roof', 0, 100, 'r1'), ret('roof', 100, 250, 'r2'), ret('roof', 250, 300, 'r3'),
], { roof: { retired_wh: '300', retirements: '3' } });
add('I08', 'Retire, accrue more, retire the new range', ['ranges', 'accrual'], [
  ...liveSite(100), ret('roof', 0, 100, 'r1'), acc('roof', 1, 250_000, { accrued_wh: 250 }), ret('roof', 100, 250, 'r2'),
], { roof: { retired_wh: '250', accrued_wh: '250' } });
add('I09', 'Simulated site retires on QWA0SIM; the live asset is untouched', ['simulated', 'zero-supply'], [
  ...simSite(50), ret('sim', 0, 50, 'flow A fictional'),
], { sim: { retired_wh: '50' } });
add('I10', 'Sequence continues from a registered start (post-reset continuation)', ['sequence'], [
  reg('roof', { next_seq: 1200 }), acc('roof', 1199, 1000, { expect: err('SeqReplay') }), acc('roof', 1200, 1000, { accrued_wh: 1 }),
], { roof: { next_seq: '1201' } });

// ----- replay, duplicate, sequence ---------------------------------------------------
add('R01', 'Replay: the same seq accepted once, the second time refused', ['replay'], [
  ...liveSite(10), acc('roof', 0, 10_000, { expect: err('SeqReplay') }),
]);
add('R02', 'Stale seq: an older batch after newer ones is refused', ['replay'], [
  ...liveSite(10), acc('roof', 1, 20_000), acc('roof', 2, 30_000), acc('roof', 1, 40_000, { expect: err('SeqReplay') }),
], { roof: { next_seq: '3', accrued_wh: '30' } });
add('R03', 'Sequence gap: seq ahead of the expected next is refused', ['invalid-sequence'], [
  ...liveSite(10), acc('roof', 2, 20_000, { expect: err('SeqGap') }), acc('roof', 1, 20_000),
], { roof: { next_seq: '2' } });
add('R04', 'Cumulative regression is refused (accrual is monotonic)', ['monotonic'], [
  ...liveSite(10), acc('roof', 1, 9_999, { expect: err('CumulativeRegression') }),
], { roof: { next_seq: '1', cumulative_mwh: '10000' } });
add('R05', 'First accrual with seq below the registered start is a replay', ['invalid-sequence'], [
  reg('roof', { next_seq: 5 }), acc('roof', 0, 1000, { expect: err('SeqReplay') }),
]);
add('D01', 'Duplicate statement on the same site is refused', ['duplicate'], [
  ...liveSite(200), ret('roof', 0, 100, 'same text'), ret('roof', 100, 200, 'same text', { expect: err('DuplicateStatement') }),
], { roof: { retired_wh: '100' } });
add('D02', 'Duplicate statement across sites (simulated → live) is refused', ['duplicate', 'contamination'], [
  ...simSite(100), ...liveSite(100), ret('sim', 0, 100, 'one statement'), ret('roof', 0, 100, 'one statement', { expect: err('DuplicateStatement') }),
], { roof: { retired_wh: '0' }, sim: { retired_wh: '100' } });
add('D03', 'Duplicate site registration is refused and the original responsible is kept', ['duplicate', 'authorization'], [
  reg('roof'), reg('roof', { responsible: 'bob', expect: err('SiteExists') }), acc('roof', 0, 5000),
  ret('roof', 0, 5, 'bob tries', { auth: ['bob'], expect: err('AUTH') }), ret('roof', 0, 5, 'alice'),
]);

// ----- overlap and range shape ---------------------------------------------------------
add('O01', 'Overlapping range (starts inside a retired range) is refused', ['overlap'], [
  ...liveSite(300), ret('roof', 0, 200, 'r1'), ret('roof', 150, 300, 'r2', { expect: err('RangeOverlap') }),
]);
add('O02', 'A range entirely inside a retired range is refused', ['overlap'], [
  ...liveSite(300), ret('roof', 0, 200, 'r1'), ret('roof', 10, 20, 'r2', { expect: err('RangeOverlap') }),
]);
add('O03', 'The exact same range again (new statement) is refused', ['overlap', 'replay'], [
  ...liveSite(300), ret('roof', 0, 200, 'r1'), ret('roof', 0, 200, 'r1 bis', { expect: err('RangeOverlap') }),
]);
add('O04', 'A range that leaves a gap is refused', ['ranges'], [
  ...liveSite(300), ret('roof', 1, 100, 'gap', { expect: err('RangeGap') }),
]);
add('O05', 'Empty range (end = start) is refused', ['ranges'], [
  ...liveSite(300), ret('roof', 0, 0, 'empty', { expect: err('EmptyRange') }),
]);
add('O06', 'Reversed range (end < start) is refused', ['ranges'], [
  ...liveSite(300), ret('roof', 0, 100, 'r1'), ret('roof', 100, 50, 'rev', { expect: err('EmptyRange') }),
]);
add('O07', 'Over-retire after a partial retirement is refused', ['over-retire', 'min-ab'], [
  ...liveSite(300), ret('roof', 0, 200, 'r1'), ret('roof', 200, 301, 'r2', { expect: err('OverRetire') }),
]);
add('O09', 'Off-by-one: a range starting 1 Wh before the retired head is an overlap', ['overlap', 'boundary'], [
  ...liveSite(300), ret('roof', 0, 200, 'r1'), ret('roof', 199, 300, 'r2', { expect: err('RangeOverlap') }), ret('roof', 200, 300, 'r2'),
], { roof: { retired_wh: '300' } });
add('O10', 'Off-by-one: a range starting 1 Wh after the retired head is a gap', ['ranges', 'boundary'], [
  ...liveSite(300), ret('roof', 0, 200, 'r1'), ret('roof', 201, 300, 'r2', { expect: err('RangeGap') }),
]);
add('R06', 'Off-by-one: seq = next − 1 is a replay, seq = next + 1 is a gap', ['replay', 'invalid-sequence', 'boundary'], [
  reg('roof', { next_seq: 10 }), acc('roof', 9, 1000, { expect: err('SeqReplay') }), acc('roof', 11, 1000, { expect: err('SeqGap') }), acc('roof', 10, 1000),
]);
add('O08', 'A refused retirement changes nothing: the same start then succeeds', ['atomicity'], [
  ...liveSite(300), ret('roof', 0, 301, 'too much', { expect: err('OverRetire') }), ret('roof', 0, 300, 'too much'),
], { roof: { retired_wh: '300', retirements: '1' } });

// ----- overflow and limits -------------------------------------------------------------
add('V01', 'Sequence overflow: an accrual at seq = u64::MAX is refused (no next seq exists)', ['overflow', 'invalid-sequence'], [
  reg('roof', { next_seq: U64_MAX }), acc('roof', U64_MAX, 1000, { expect: err('Overflow') }),
], { roof: { next_seq: U64_MAX, cumulative_mwh: '0' } });
add('V02', 'Seq u64::MAX − 1 is the last accrual that can be accepted', ['overflow', 'boundary'], [
  reg('roof', { next_seq: (BigInt(U64_MAX) - 1n).toString() }), acc('roof', (BigInt(U64_MAX) - 1n).toString(), 1000, { accrued_wh: 1 }),
  acc('roof', U64_MAX, 2000, { expect: err('Overflow') }),
], { roof: { next_seq: U64_MAX } });
add('V03', 'u128::MAX cumulative is accepted and floors exactly', ['overflow', 'flooring', 'boundary'], [
  reg('roof'), acc('roof', 0, U128_MAX, { accrued_wh: (BigInt(U128_MAX) / 1000n).toString() }),
]);
add('V04', 'A retirement above the classic asset limit (i64::MAX stroops) is refused', ['overflow', 'limit'], [
  reg('roof'), acc('roof', 0, U128_MAX), ret('roof', 0, (BigInt(MAX_RETIRE_WH) + 1n).toString(), 'huge', { expect: err('AmountTooLarge') }),
]);
add('V05', 'The largest allowed retirement (922,337,203,685,477,580 Wh) passes', ['limit', 'boundary'], [
  reg('roof'), acc('roof', 0, U128_MAX), ret('roof', 0, MAX_RETIRE_WH, 'largest'),
], { roof: { retired_wh: MAX_RETIRE_WH } });
add('V06', 'A range of the whole u128 accrual is refused as too large, not wrapped', ['overflow', 'limit'], [
  reg('roof'), acc('roof', 0, U128_MAX), ret('roof', 0, (BigInt(U128_MAX) / 1000n).toString(), 'all', { expect: err('AmountTooLarge') }),
]);

// ----- authorization -------------------------------------------------------------------
add('A01', 'Accrual by an unrelated key is refused', ['unauthorized'], [
  reg('roof'), acc('roof', 0, 1000, { auth: ['mallory'], expect: err('AUTH') }),
]);
add('A02', 'One-key relay: proposer alone is refused', ['unauthorized', 'two-key-relay'], [
  reg('roof'), acc('roof', 0, 1000, { auth: ['proposer'], expect: err('AUTH') }),
]);
add('A03', 'One-key relay: verifier alone is refused', ['unauthorized', 'two-key-relay'], [
  reg('roof'), acc('roof', 0, 1000, { auth: ['verifier'], expect: err('AUTH') }),
]);
add('A04', 'Retirement by someone other than the responsible party is refused', ['unauthorized'], [
  ...liveSite(100), ret('roof', 0, 100, 'm', { auth: ['mallory'], expect: err('AUTH') }),
  ret('roof', 0, 100, 'g', { auth: ['governance'], expect: err('AUTH') }),
]);
add('A05', 'The relay cannot retire', ['unauthorized', 'separation'], [
  ...liveSite(100), ret('roof', 0, 100, 'relay', { auth: RELAY, expect: err('AUTH') }),
]);
add('A06', 'Only governance registers sites', ['unauthorized'], [
  reg('roof', { auth: ['alice'], expect: err('AUTH') }), reg('roof', { auth: RELAY, expect: err('AUTH') }),
]);
add('A07', 'Only governance freezes and pauses', ['unauthorized'], [
  reg('roof'), frz('roof', true, { auth: ['mallory'], expect: err('AUTH') }), pause(true, { auth: ['proposer'], expect: err('AUTH') }),
  acc('roof', 0, 1000),
]);
add('A08', 'Governance cannot accrue on its own', ['unauthorized', 'separation'], [
  reg('roof'), acc('roof', 0, 1000, { auth: GOV, expect: err('AUTH') }),
]);
add('A09', 'Relay rotation: the old keys stop working, the new pair works', ['authorization', 'rotation'], [
  reg('roof'), relay('relay2a', 'relay2b'), acc('roof', 0, 1000, { expect: err('AUTH') }),
  acc('roof', 0, 1000, { auth: ['relay2a', 'relay2b'] }),
]);
add('A10', 'Relay rotation to one key for both roles is refused', ['two-key-relay'], [
  relay('relay2a', 'relay2a', { expect: err('SameRelayKey') }), relay('relay2a', 'relay2b', { auth: ['mallory'], expect: err('AUTH') }),
]);

// ----- evidence levels and contamination -----------------------------------------------
add('E01', 'Simulated (A0) batch on a live site is refused', ['contamination'], [
  reg('roof'), acc('roof', 0, 1000, { level: 0, expect: err('LevelMismatch') }),
]);
add('E02', 'Measured (A2) batch on a simulated site is refused', ['contamination'], [
  reg('sim', { cls: 0 }), acc('sim', 0, 1000, { level: 2, expect: err('LevelMismatch') }),
]);
add('E03', 'Single-meter (A1) batch on a simulated site is refused; A1 on a live site passes', ['contamination', 'evidence-level'], [
  reg('sim', { cls: 0 }), reg('roof'), acc('sim', 0, 1000, { level: 1, expect: err('LevelMismatch') }), acc('roof', 0, 1000, { level: 1 }),
]);
add('E04', 'Unknown evidence level is refused', ['evidence-level'], [
  reg('roof'), acc('roof', 0, 1000, { level: 3, expect: err('InvalidLevel') }),
]);
add('E05', 'Unknown data class is refused at registration', ['evidence-level'], [
  reg('roof', { cls: 2, expect: err('InvalidClass') }), acc('roof', 0, 1000, { expect: err('SiteNotFound') }),
]);
add('E06', 'Contamination is refused even with an otherwise valid next batch, and the site continues', ['contamination', 'atomicity'], [
  ...liveSite(10), acc('roof', 1, 20_000, { level: 0, expect: err('LevelMismatch') }), acc('roof', 1, 20_000, { level: 2, accrued_wh: 20 }),
]);

// ----- freeze and pause ----------------------------------------------------------------
add('F01', 'Frozen site: accrual and retirement refused; unfrozen they pass', ['frozen'], [
  ...liveSite(100), frz('roof', true), acc('roof', 1, 200_000, { expect: err('SiteFrozen') }),
  ret('roof', 0, 100, 'f', { expect: err('SiteFrozen') }), frz('roof', false), acc('roof', 1, 200_000), ret('roof', 0, 100, 'f'),
]);
add('F02', 'Freezing an unknown site is refused', ['frozen'], [frz('ghost', true, { expect: err('SiteNotFound') })]);
add('F03', 'Freeze is checked before the sequence (frozen + replay → SiteFrozen)', ['frozen', 'order'], [
  ...liveSite(10), frz('roof', true), acc('roof', 0, 10_000, { expect: err('SiteFrozen') }),
]);
add('F04', 'Freezing one site leaves the others running', ['frozen'], [
  reg('a'), reg('b'), frz('a', true), acc('a', 0, 1000, { expect: err('SiteFrozen') }), acc('b', 0, 1000),
]);
add('P01', 'Paused: register, accrue and retire refused; unpaused they pass', ['pause'], [
  ...liveSite(100), pause(true), reg('b', { expect: err('Paused') }), acc('roof', 1, 200_000, { expect: err('Paused') }),
  ret('roof', 0, 100, 'p', { expect: err('Paused') }), pause(false), acc('roof', 1, 200_000), ret('roof', 0, 100, 'p'),
]);
add('P02', 'Freeze still works while paused (emergency control)', ['pause', 'frozen'], [
  reg('roof'), pause(true), frz('roof', true), pause(false), acc('roof', 0, 1000, { expect: err('SiteFrozen') }),
]);
add('P03', 'Order: an unauthorized accrual while paused is AUTH; an unauthorized retirement while paused is Paused', ['pause', 'order'], [
  ...liveSite(100), pause(true), acc('roof', 1, 1, { auth: ['mallory'], expect: err('AUTH') }),
  ret('roof', 0, 1, 'x', { auth: ['mallory'], expect: err('Paused') }),
]);
add('P04', 'Relay rotation is refused while paused', ['pause', 'rotation'], [pause(true), relay('relay2a', 'relay2b', { expect: err('Paused') })]);

// ----- unknown sites -------------------------------------------------------------------
add('N01', 'Accrual for an unregistered site is refused', ['unknown-site'], [acc('ghost', 0, 1000, { expect: err('SiteNotFound') })]);
add('N02', 'Retirement for an unregistered site is refused before any signature is checked', ['unknown-site', 'order'], [
  ret('ghost', 0, 1, 'x', { auth: ['mallory'], expect: err('SiteNotFound') }),
]);
add('N03', 'Level is checked before the sequence (contamination + replay → LevelMismatch)', ['order', 'contamination'], [
  ...liveSite(10), acc('roof', 0, 10_000, { level: 0, expect: err('LevelMismatch') }),
]);

const doc = {
  spec: 'qwatt-issuance conformance cases v1',
  note: 'Integers are decimal strings. site/batch/statement are labels hashed with domain tags (model/model.mjs siteId, batchHash, statementHash). auth lists the actors who authorized the call; AUTH means a required authorization was missing.',
  actors: ['governance', 'proposer', 'verifier', 'alice', 'bob', 'mallory', 'relay2a', 'relay2b'],
  setup: { governance: 'governance', proposer: 'proposer', verifier: 'verifier' },
  cases,
};
const text = JSON.stringify(doc, null, 1) + '\n';
if (process.argv.includes('--check')) {
  if (readFileSync(OUT, 'utf8') !== text) { console.error('issuance-cases.json is stale: run node fixtures/build-cases.mjs'); process.exit(1); }
  console.log(`issuance-cases.json is current (${cases.length} cases)`);
} else {
  writeFileSync(OUT, text);
  console.log(`wrote ${cases.length} cases, ${cases.reduce((n, c) => n + c.steps.length, 0)} steps → ${OUT}`);
}
